ASTRONOMY_BY_ID: Dict[str, Dict[str, Any]] = {q['id']: q for q in ASTRONOMY_QUESTIONS}

ASTRONOMY_BY_SUBMODE: Dict[str, List[Dict[str, Any]]] = {
    "telescope_zoom": [q for q in ASTRONOMY_QUESTIONS if q["sub_mode"] == "telescope_zoom"],
    "cosmic_scale": [q for q in ASTRONOMY_QUESTIONS if q["sub_mode"] == "cosmic_scale"],
    "constellations": [q for q in ASTRONOMY_QUESTIONS if q["sub_mode"] == "constellations"],
    "space_missions": [q for q in ASTRONOMY_QUESTIONS if q["sub_mode"] == "space_missions"],
}

def get_astronomy_question_by_id(question_id: str) -> Optional[Dict[str, Any]]:
    return ASTRONOMY_BY_ID.get(question_id)

def get_astronomy_questions_by_submode(sub_mode: str) -> List[Dict[str, Any]]:
    return ASTRONOMY_BY_SUBMODE.get(sub_mode, [])

def get_random_astronomy_questions(count: int = 1, sub_mode: Optional[str] = None) -> List[Dict[str, Any]]:
    pool = get_astronomy_questions_by_submode(sub_mode) if sub_mode else ASTRONOMY_QUESTIONS
    if not pool:
        return []
    return random.sample(pool, min(count, len(pool)))
